class Solution:
    def circularPermutation(self, n: int, start: int) -> List[int]:
        total = 1 << n
        used = [False] * total
        res = []

        def dfs(cur):
            res.append(cur)
            used[cur] = True
            if len(res) == total:
                return bin(res[-1] ^ start).count('1') == 1
            for b in range(n):
                nxt = cur ^ (1 << b)
                if not used[nxt] and dfs(nxt):
                    return True
            used[cur] = False
            res.pop()
            return False

        dfs(start)
        return res

