class Solution {
public:
    vector<int> circularPermutation(int n, int start) {
        int total = 1 << n;
        vector<int> res;
        vector<bool> used(total, false);
        function<bool(int)> dfs = [&](int cur) -> bool {
            res.push_back(cur);
            used[cur] = true;
            if ((int)res.size() == total)
                return __builtin_popcount(res.back() ^ start) == 1;
            for (int b = 0; b < n; b++) {
                int nxt = cur ^ (1 << b);
                if (!used[nxt] && dfs(nxt)) return true;
            }
            used[cur] = false;
            res.pop_back();
            return false;
        };
        dfs(start);
        return res;
    }
};

