class Solution {
    private List<Integer> res = new ArrayList<>();
    private boolean[] used;
    private int start, total;

    public List<Integer> circularPermutation(int n, int start) {
        this.start = start;
        total = 1 << n;
        used = new boolean[total];
        dfs(start);
        return res;
    }

    private boolean dfs(int cur) {
        res.add(cur);
        used[cur] = true;
        if (res.size() == total)
            return Integer.bitCount(res.get(res.size() - 1) ^ start) == 1;
        for (int b = 0; b < 16 && (1 << b) < total; b++) {
            int nxt = cur ^ (1 << b);
            if (!used[nxt] && dfs(nxt)) return true;
        }
        used[cur] = false;
        res.remove(res.size() - 1);
        return false;
    }
}

