var circularPermutation = function(n, start) {
    const total = 1 << n;
    const used = new Array(total).fill(false);
    const res = [];
    const popcount = x => { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; };
    function dfs(cur) {
        res.push(cur);
        used[cur] = true;
        if (res.length === total) return popcount(res[res.length - 1] ^ start) === 1;
        for (let b = 0; b < n; b++) {
            const nxt = cur ^ (1 << b);
            if (!used[nxt] && dfs(nxt)) return true;
        }
        used[cur] = false;
        res.pop();
        return false;
    }
    dfs(start);
    return res;
};

